def is_valid_time(time):
    hh, mm = map(int, time.split(':'))
    return 0 <= hh <= 23 and 0 <= mm <= 59

def increment_time(time):
    hh, mm = map(int, time.split(':'))
    mm += 1
    if mm == 60:
        mm = 0
        hh += 1
        if hh == 24:
            hh = 0
    return f"{hh:02}:{mm:02}"

def decrement_time(time):
    hh, mm = map(int, time.split(':'))
    mm -= 1
    if mm == -1:
        mm = 59
        hh -= 1
        if hh == -1:
            hh = 23
    return f"{hh:02}:{mm:02}"

def get_all_times(original, current):
    times = set()
    queue = [original]
    visited = set()

    while queue:
        time = queue.pop(0)
        if time in visited:
            continue
        visited.add(time)
        times.add(time)

        if time == current:
            continue

        # Increment each digit
        for i in range(4):
            new_time = list(time)
            if new_time[i] == '9':
                new_time[i] = '0'
            else:
                new_time[i] = str(int(new_time[i]) + 1)
            new_time = ''.join(new_time)
            if is_valid_time(new_time):
                queue.append(new_time)

        # Decrement each digit
        for i in range(4):
            new_time = list(time)
            if new_time[i] == '0':
                new_time[i] = '9'
            else:
                new_time[i] = str(int(new_time[i]) - 1)
            new_time = ''.join(new_time)
            if is_valid_time(new_time):
                queue.append(new_time)

    return sorted(times)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    original_time = data[0]
    current_time = data[1]

    times = get_all_times(original_time, current_time)
    print(len(times))
    for time in times:
        print(time)

