def get_next_times(current_time):
    hh, mm = map(int, current_time.split(':'))
    next_times = []

    # Increment minutes
    if mm < 59:
        next_times.append(f"{hh:02}:{mm+1:02}")
    else:
        next_times.append(f"{(hh+1)%24:02}:00")

    # Decrement minutes
    if mm > 0:
        next_times.append(f"{hh:02}:{mm-1:02}")
    else:
        next_times.append(f"{(hh-1)%24:02}:59")

    # Increment hours
    if hh < 23:
        next_times.append(f"{hh+1:02}:{mm:02}")
    else:
        next_times.append(f"00:{mm:02}")

    # Decrement hours
    if hh > 0:
        next_times.append(f"{hh-1:02}:{mm:02}")
    else:
        next_times.append(f"23:{mm:02}")

    return next_times

def bfs(start_time, end_time):
    queue = [start_time]
    visited = set([start_time])
    path = {start_time: None}

    while queue:
        current_time = queue.pop(0)

        if current_time == end_time:
            break

        for next_time in get_next_times(current_time):
            if next_time not in visited:
                visited.add(next_time)
                queue.append(next_time)
                path[next_time] = current_time

    # Reconstruct the path
    result = []
    while end_time:
        result.append(end_time)
        end_time = path[end_time]

    return result[::-1]

def main():
